int ota_boot2_do_fallback(link_entry new_link)
{
    MiscDataInfo info;
    int ret = 0;
    bootinfo_block block;

    if (new_link >= LINK_INVALID) {
        TRACE(0, "error %s %d, new_link:%d", __func__, __LINE__, new_link);
        return ERR_PARAMETER;
    }

    block = ota_get_valid_bootinfo_block();
    ota_get_bootinfo(&info, block, ota_get_bootinfo_zone_num(block));
    if (new_link == LINK_BOOT2A || new_link == LINK_BOOT2B) {
        info.curbootArea = new_link;
    }else if (new_link == LINK_CM33_MAIN) {
        info.upgMode = UPG_MODE_NORMAL;
    }else if (new_link == LINK_CM33_MINI) {
        info.upgMode = UPG_MODE_OTA;
    }

    ret = ota_set_bootinfo_to_zoneAB(&info);
    if (ret) {
        TRACE(0, "error %s %d, ret:%d", __func__, __LINE__, ret);
        return ERR_RETURN;
    }

    return ret;
}

int ota_check_pmu_watchdog(void)
{
	int exception_reboot = 0;
	uint16_t val = 0;

	pmu_read(0x61, &val);
	TRACE(0, "%s 0x61=0x%x", __func__, val);
	val = val & 0x7fff;
	switch (val) {
		case 0:
			/* normal reboot */
			break;

		case 1:
			/* factory reboot */
			//hal_sw_bootmode_set(HAL_SW_BOOTMODE_TEST_MODE | HAL_SW_BOOTMODE_TEST_NOSIGNALINGMODE_WIFI);
			break;

		case 0x6666:
			/* watchdog reboot with exception */
			exception_reboot = 1;
			break;

		default:
			/* charger power on */
			break;
	}
	if (val != 0) {
		pmu_write(0x61, 0x0); //normal reboot
	}

